import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const VERSION = "R9.5 Library Sort + Grid";
const TARGET_REL = "src/features/music/MusicPage.tsx";
const EXPECTED_SHA256 = "d9cd3a14ab8487c2dc658b7d1653db656b101b73dfcf01926e18f8b16e57cb61";
const PAYLOAD = "";

function sha256(buffer) {
  return crypto.createHash("sha256").update(buffer).digest("hex");
}
function findRepoRoot(start) {
  let current = path.resolve(start);
  for (let i = 0; i < 8; i += 1) {
    if (fs.existsSync(path.join(current, "package.json")) && fs.existsSync(path.join(current, "src"))) return current;
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return null;
}
function findMusicPage(repo) {
  const preferred = path.join(repo, TARGET_REL);
  if (fs.existsSync(preferred)) return preferred;
  const srcRoot = path.join(repo, "src");
  const matches = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (entry.name === "node_modules" || entry.name === ".git") continue;
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.isFile() && entry.name === "MusicPage.tsx") {
        const body = fs.readFileSync(full, "utf8");
        if (body.includes("Song Library") && body.includes("songSort") && body.includes("tr10-actions")) matches.push(full);
      }
    }
  };
  if (fs.existsSync(srcRoot)) walk(srcRoot);
  return matches.length === 1 ? matches[0] : null;
}

const repo = findRepoRoot(process.cwd());
if (!repo) {
  console.error("Could not find the MVP Trainer repo root. Run this installer from the repo or its scripts folder.");
  process.exit(1);
}
const target = findMusicPage(repo);
if (!target) {
  console.error("Could not uniquely locate MusicPage.tsx. No files were changed.");
  process.exit(1);
}
const payload = Buffer.from(PAYLOAD, "base64");
if (sha256(payload) !== EXPECTED_SHA256) {
  console.error("Installer payload verification failed. No files were changed.");
  process.exit(1);
}
if (fs.existsSync(target) && sha256(fs.readFileSync(target)) === EXPECTED_SHA256) {
  console.log(`${VERSION} is already installed.`);
  console.log(`Target: ${path.relative(repo, target)}`);
  process.exit(0);
}
const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupDir = path.join(repo, ".mvp-backups", `r9-5-library-sort-grid-${stamp}`);
fs.mkdirSync(backupDir, { recursive: true });
if (fs.existsSync(target)) {
  const rel = path.relative(repo, target);
  const backup = path.join(backupDir, rel);
  fs.mkdirSync(path.dirname(backup), { recursive: true });
  fs.copyFileSync(target, backup);
}
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, payload);
const installedHash = sha256(fs.readFileSync(target));
if (installedHash !== EXPECTED_SHA256) {
  console.error("Post-write verification failed. Restore from backup:", backupDir);
  process.exit(1);
}
console.log(`Installed ${VERSION}.`);
console.log(`Updated: ${path.relative(repo, target)}`);
console.log(`Backup: ${path.relative(repo, backupDir)}`);
console.log("Next: run npm run build from the repo root.");
